// ==================== 辅助查找 ====================

/**
 * 按 namespace 获取枪械数据
 * @param {"tacz" | "lavender" | "bf1"} namespace - 枪包命名空间
 * @returns {Array<{id: TaczGunId, name: string, type: string, ammo: TaczAmmoId, slots: string[]}>}
 */
declare function getTaczGuns(namespace: string): any[];

/**
 * 获取指定枪械的配件兼容槽位
 * @param {TaczGunId} gunId
 * @returns {string[]} 支持的配件槽位列表 (scope, muzzle, stock, grip, laser, extended_mag)
 */
declare function getTaczGunSlots(gunId: string): string[];
